// This file is generated by AI.

// 模板管理 (内联组件, 用于设置对话框"模板"页): 添加/移除模板 (引用式存储, 不复制)。

import { open } from '@tauri-apps/plugin-dialog';
import { Button } from '@fluentui/react-components';
import { AddRegular, DeleteRegular, FolderOpenRegular } from '@fluentui/react-icons';
import { useState } from 'react';

import { createId, validateTemplate } from '../lib/engineTemplate';
import { useAppStore } from '../state/store';

export function TemplateManager() {
  const settings = useAppStore((s) => s.settings);
  const updateSettings = useAppStore((s) => s.updateSettings);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const addTemplate = async () => {
    setError(null);
    const dir = await open({ directory: true, title: '选择 WebGAL 模板目录' });
    if (typeof dir !== 'string') return;
    setBusy(true);
    const v = await validateTemplate(dir);
    setBusy(false);
    if (!v.valid) {
      setError(v.error ?? '无效的模板目录');
      return;
    }
    if (settings.templates.some((t) => t.path === dir)) {
      setError('该模板已添加');
      return;
    }
    updateSettings({
      templates: [...settings.templates, { id: createId(), name: v.name, path: dir }],
    });
  };

  const removeTemplate = (id: string) => updateSettings({ templates: settings.templates.filter((t) => t.id !== id) });

  return (
    <div className="template-manager">
      <div className="manager-section-head">
        <h3 className="manager-section-title">模板</h3>
        <Button appearance="primary" icon={<AddRegular />} disabled={busy} onClick={() => void addTemplate()}>
          添加模板
        </Button>
      </div>

      {settings.templates.length === 0 ? (
        <span className="muted">尚未添加模板 (默认使用引擎内置模板)</span>
      ) : (
        <ul className="manager-list">
          {settings.templates.map((t) => (
            <li key={t.id} className="manager-item" title={t.path}>
              <FolderOpenRegular />
              <span className="manager-item-name">{t.name}</span>
              <span className="manager-item-path">{t.path}</span>
              <button className="manager-item-remove" title="移除" onClick={() => removeTemplate(t.id)}>
                <DeleteRegular />
              </button>
            </li>
          ))}
        </ul>
      )}

      {error ? <p className="prompt-error">{error}</p> : null}
    </div>
  );
}
